import PyPDF2
import io
from PIL import Image

def extract_images(pdf_path):
    with open(pdf_path, 'rb') as file:
        pdf = PyPDF2.PdfReader(file)

        for page_num in range(len(pdf.pages)):
            page = pdf.pages[page_num]
            if '/Resources' in page and '/XObject' in page['/Resources']:
                xObject = page['/Resources']['/XObject']

                for obj in xObject:
                    if xObject[obj]['/Subtype'] == '/Image':
                        try:
                            print(f"\nImage found on page {page_num + 1}:")
                            print(f"Type: {xObject[obj]['/Filter']}")
                            print(f"Bits per component: {xObject[obj].get('/BitsPerComponent', 'N/A')}")
                            print(f"Color space: {xObject[obj].get('/ColorSpace', 'N/A')}")
                            print(f"Width: {xObject[obj]['/Width']}")
                            print(f"Height: {xObject[obj]['/Height']}")
                        except Exception as e:
                            print(f"Error analyzing image: {str(e)}")

if __name__ == "__main__":
    extract_images("/home/ctfplayer/ctf_files/SPBlock_Email.pdf")

import PyPDF2

def extract_text(pdf_path):
    with open(pdf_path, 'rb') as file:
        pdf = PyPDF2.PdfReader(file)

        for page_num in range(len(pdf.pages)):
            print(f"\n=== Page {page_num + 1} ===\n")
            text = pdf.pages[page_num].extract_text()
            print(text)

